    if not grid:
        return []
    h, w = len(grid), len(grid[0])

    # Across each row, the sequence shifts by one at the diagonal:
    # cells left of the diagonal use phase c, while cells on/right of it
    # use phase c-1. Infer the repeating color cycle from nonzero cells.
    period = None
    cycle = None
    for p in range(1, w + 1):
        vals = {}
        valid = True
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value == 0:
                    continue
                phase = c if c < r else c - 1
                k = phase % p
                if k in vals and vals[k] != value:
                    valid = False
                    break
                vals[k] = value
            if not valid:
                break
        if valid:
            period, cycle = p, vals
            break

    if period is None:
        # A row-derived fallback, though valid task grids should infer a cycle.
        period = w
        cycle = {}
        for c, value in enumerate(grid[0]):
            if value:
                cycle[(c - 1) % period] = value

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                phase = c if c < r else c - 1
                out[r][c] = cycle[phase % period]
    return out
